commands.command:
/usr/bin/zsh -lc "awk '
  /href=\"#work\"/ { links++ }
  /id=\"work\"/ { target++ }
  /FIELD NOTES/ { brand++ }
  /A quiet study\\./ { heading++ }
  /An independent film practice\\./ { intro++ }
  />Explore</ { explore++ }
  />Selected work</ { work++ }
  END {
    if (links == 2 && target == 1 && brand >= 1 && heading >= 1 && intro == 1 && explore == 1 && work == 1) {
      print \"PASS: required copy and both #work links are present; target is unique.\"
    } else { print \"FAIL: content or anchor mismatch.\"; exit 1 }
  }
' index.html
if rg -n '<script|<video|https?://|@import|animation:' index.html; then
  exit 1
else
  echo 'PASS: no scripts, video, external requests, imports, or animation declarations.'
fi
sha256sum reference.svg"
